import { z } from "zod";
import type { Db } from "./db.js";
import { ensureProfile } from "./users.js";

const Common = z.object({
  // Generated by the app when the event happens, so a retried upload is stored once.
  id: z.uuid(),
  // e.g. "es-v1", or "es-duel" for a duel. Checked against real content once it's in the database.
  clipId: z.string().regex(/^[a-z]{2}-[a-z0-9]{1,16}$/, "must look like es-v1"),
  occurredAt: z.iso.datetime({ offset: true }),
});

const kind = <K extends string, P extends z.ZodRawShape>(name: K, payload: P) =>
  Common.extend({ kind: z.literal(name), payload: z.object(payload).strict() }).strict();

// What the app reports. Each kind has a strict payload, so nothing unexpected gets stored.
// Scores and XP are never taken from here: the server derives them from these facts.
const Event = z.discriminatedUnion("kind", [
  kind("clip_viewed", {}),
  kind("card_flipped", {}),
  kind("quiz_answered", { firstTry: z.boolean() }),
  // The browser scores speech locally, so the server can only bound it, not check it.
  kind("speech_scored", { score: z.int().min(0).max(100) }),
  kind("review_graded", { grade: z.enum(["again", "good", "easy"]) }),
  kind("clip_saved", { saved: z.boolean() }),
  kind("duel_finished", { won: z.boolean() }),
]);

export const MAX_BATCH = 100;
// The app queues events while offline. Older ones are refused as stale.
const MAX_AGE_MS = 30 * 24 * 60 * 60 * 1000;
// Allow for phones whose clocks run a little fast.
const MAX_SKEW_MS = 5 * 60 * 1000;

// A malformed batch is a bug in the app, so the whole request fails with a 400.
export const EventBatch = z.object({ events: z.array(Event).min(1).max(MAX_BATCH) }).strict();

export type AppEvent = z.infer<typeof Event>;

/**
 * Why an otherwise well-formed event can't be stored, or null if it can. These are refused
 * one by one rather than failing the batch: a single stale event must not wedge the app's
 * upload queue behind it forever.
 */
export function refusal(e: AppEvent, now = Date.now()): string | null {
  const t = Date.parse(e.occurredAt);
  if (t > now + MAX_SKEW_MS) return "occurred_in_future";
  if (t < now - MAX_AGE_MS) return "too_old";
  return null;
}

/**
 * Stores events for one learner. Events already stored (a retry, or a repeat within the batch)
 * are skipped, so uploading the same batch twice has no extra effect.
 * Returns the ids that were new.
 */
export async function storeEvents(db: Db, userId: string, events: AppEvent[]): Promise<string[]> {
  if (!events.length) return [];
  await ensureProfile(db, userId);
  const { rows } = await db.query<{ id: string }>(
    `insert into app.events (user_id, id, kind, clip_id, payload, occurred_at)
     select $1, e.id, e.kind, e.clip_id, e.payload, e.occurred_at
       from unnest($2::uuid[], $3::text[], $4::text[], $5::jsonb[], $6::timestamptz[])
            as e(id, kind, clip_id, payload, occurred_at)
     on conflict (user_id, id) do nothing
     returning id`,
    [
      userId,
      events.map((e) => e.id),
      events.map((e) => e.kind),
      events.map((e) => e.clipId),
      events.map((e) => JSON.stringify(e.payload)),
      events.map((e) => e.occurredAt),
    ],
  );
  return rows.map((r) => r.id);
}
